import { getDb, DatabaseUnavailableError } from '../db';
import { createLogger } from '../_core/logger';

const logger = createLogger('database', { component: 'DeploymentPersistence' });
import { deploymentRecords, deploymentScans, monitorCycles, governanceDeploySnapshots } from '../../drizzle/schema';
import { desc, eq, sql } from 'drizzle-orm';
import type { MonitorCycleResult } from './autonomous-experiment-monitor';

export async function persistDeploymentRecord(record: {
  deploymentId: string;
  status: string;
  source: string;
  patchCount: number;
  filesAffected: string[];
  durationMs: number;
  error?: string;
  metadata?: Record<string, unknown>;
}): Promise<void> {
  try {
    const db = await getDb();
    if (!db) throw new DatabaseUnavailableError('Database unavailable: cannot persist deployment record');
    await db.insert(deploymentRecords).values({
      deploymentId: record.deploymentId,
      status: record.status,
      source: record.source,
      patchCount: record.patchCount,
      filesAffected: JSON.stringify(record.filesAffected),
      durationMs: record.durationMs,
      error: record.error || null,
      metadata: record.metadata ? JSON.stringify(record.metadata) : null,
      createdAt: Date.now(),
    });
  } catch (err) {
    logger.error({ err, operation: 'deploy', deploymentId: record.deploymentId }, 'Failed to persist deployment record');
  }
}

export async function getDeploymentRecords(limit = 50) {
  try {
    const db = await getDb();
    if (!db) throw new DatabaseUnavailableError('Database unavailable: cannot read deployment records');
    return await db.select().from(deploymentRecords).orderBy(desc(deploymentRecords.createdAt)).limit(limit);
  } catch { return []; }
}

export async function getDeploymentRecord(deploymentId: string) {
  try {
    const db = await getDb();
    if (!db) throw new DatabaseUnavailableError('Database unavailable: cannot read deployment record');
    const r = await db.select().from(deploymentRecords).where(eq(deploymentRecords.deploymentId, deploymentId)).limit(1);
    return r[0] || null;
  } catch { return null; }
}

export async function persistScanResult(scan: {
  scanId: string;
  deploymentId: string;
  overallScore: number;
  passed: boolean;
  checksRun: number;
  checksPassed: number;
  checksFailed: number;
  details?: Record<string, unknown>;
}): Promise<void> {
  try {
    const db = await getDb();
    if (!db) throw new DatabaseUnavailableError('Database unavailable: cannot persist scan result');
    await db.insert(deploymentScans).values({
      scanId: scan.scanId,
      deploymentId: scan.deploymentId,
      overallScore: scan.overallScore,
      passed: scan.passed ? 1 : 0,
      checksRun: scan.checksRun,
      checksPassed: scan.checksPassed,
      checksFailed: scan.checksFailed,
      details: scan.details ? JSON.stringify(scan.details) : null,
      createdAt: Date.now(),
    });
  } catch (err) {
    logger.error({ err, operation: 'scan', scanId: scan.scanId }, 'Failed to persist scan result');
  }
}

export async function getScanResults(limit = 50) {
  try {
    const db = await getDb();
    if (!db) throw new DatabaseUnavailableError('Database unavailable: cannot read scan results');
    return await db.select().from(deploymentScans).orderBy(desc(deploymentScans.createdAt)).limit(limit);
  } catch { return []; }
}

export async function getScansForDeployment(deploymentId: string) {
  try {
    const db = await getDb();
