    return await db.select().from(deploymentScans).where(eq(deploymentScans.deploymentId, deploymentId));
  } catch { return []; }
}

export async function persistMonitorCycle(cycle: MonitorCycleResult): Promise<void> {
  try {
    const db = await getDb();
    if (!db) throw new DatabaseUnavailableError('Database unavailable: cannot persist monitor cycle');
    await db.insert(monitorCycles).values({
      cycleId: cycle.cycleId,
      startedAt: cycle.startedAt,
      completedAt: cycle.completedAt,
      experimentsChecked: cycle.experimentsChecked,
      promoted: JSON.stringify(cycle.promoted),
      rolledBack: JSON.stringify(cycle.rolledBack),
      ongoing: JSON.stringify(cycle.ongoing),
      errors: JSON.stringify(cycle.errors),
      createdAt: Date.now(),
    });
  } catch (err) {
    logger.error({ err, operation: 'monitor', cycleId: cycle.cycleId }, 'Failed to persist monitor cycle');
  }
